    if (pat[0] == '?')
        for (int c = 0; c < 26; ++c) f[c] = 1;
    else
        f[pat[0] - 'a'] = 1;

    // 当前前缀总方案数
    long long total = 0;
    for (int c = 0; c < 26; ++c) total += f[c];
    total %= MOD;

    for (int i = 1; i < m; ++i) {
        vector<long long> nf(26, 0);  // 下一轮 f
        if (pat[i] == '?') {
            // 通配符：每个字符 c 不能和上一位相同
            for (int c = 0; c < 26; ++c)
                nf[c] = (total - f[c] + MOD) % MOD;
